-- Demo data: Rangoli Designer Boutique + Gitanjali Store (ladies handbags & purses).
-- Run AFTER the business-page migrations (same as hospital-demo-data.sql).
-- Images ship in storage/app/public/uploads/demo/{rangoli-boutique,gitanjali-store}/.
-- Logins: rangoliboutique.globallife@gmail.com / Password!123  and  gitanjalistore.globallife@gmail.com / Password!123
SET NAMES utf8mb4;
START TRANSACTION;

-- Existing records this data hangs off (same fallbacks as the hospital demo).
SET @city = COALESCE((SELECT id FROM cities WHERE slug = 'jhansi' LIMIT 1), (SELECT id FROM cities ORDER BY id LIMIT 1));
SET @plan_b = COALESCE((SELECT id FROM vip_plans WHERE slug = 'professional' LIMIT 1), (SELECT id FROM vip_plans ORDER BY product_limit DESC LIMIT 1));
SET @plan_g = COALESCE((SELECT id FROM vip_plans WHERE slug = 'growth-plus' LIMIT 1), (SELECT id FROM vip_plans ORDER BY product_limit DESC LIMIT 1));
-- Package expiry = activation date + validity months of the package.
SET @expires_b = DATE_ADD('2026-11-01 10:00:00', INTERVAL COALESCE((SELECT validity_months FROM vip_plans WHERE id = @plan_b), 12) MONTH);
SET @expires_g = DATE_ADD('2026-11-01 10:00:00', INTERVAL COALESCE((SELECT validity_months FROM vip_plans WHERE id = @plan_g), 12) MONTH);
SET @partner = COALESCE((SELECT id FROM users WHERE email = 'jhansi.managerA@globallife.co.in' LIMIT 1), (SELECT u.id FROM model_has_roles mr JOIN roles r ON r.id = mr.role_id JOIN users u ON u.id = mr.model_id WHERE r.name = 'commission_partner' AND mr.model_type = 'App\\Models\\User' ORDER BY u.id LIMIT 1));
INSERT IGNORE INTO `roles` (`name`, `guard_name`, `created_at`, `updated_at`) VALUES ('vip_member', 'web', NOW(), NOW());

-- Safe to re-run: first remove any earlier copy of THESE TWO demo stores (and nothing else).
-- Also clears copies left under earlier addresses (@globallife.in, @globallife.co.in) by older imports.
-- Deleting the owner cascades to their business page and all its banners, services, products,
-- gallery, FAQs, reviews and sections. The role link has no foreign key, so it is removed by hand.
DELETE FROM `model_has_roles` WHERE `model_type` = 'App\\Models\\User' AND `model_id` IN (SELECT `id` FROM `users` WHERE `email` IN ('rangoliboutique.globallife@gmail.com', 'gitanjalistore.globallife@gmail.com', 'boutique@globallife.co.in', 'gitanjali@globallife.co.in', 'boutique@globallife.in', 'gitanjali@globallife.in'));
DELETE FROM `users` WHERE `email` IN ('rangoliboutique.globallife@gmail.com', 'gitanjalistore.globallife@gmail.com', 'boutique@globallife.co.in', 'gitanjali@globallife.co.in', 'boutique@globallife.in', 'gitanjali@globallife.in');

-- ===================== Rangoli Designer Boutique =====================
-- Owner login: rangoliboutique.globallife@gmail.com / Password!123
INSERT INTO `users` (`name`, `email`, `mobile`, `email_verified_at`, `password`, `status`, `commission_percentage`, `created_by`, `two_factor_secret`, `two_factor_recovery_codes`, `two_factor_confirmed_at`, `remember_token`, `created_at`, `updated_at`)
VALUES ('Neha Srivastava', 'rangoliboutique.globallife@gmail.com', '9876500021', '2026-11-13 10:00:00', '$2y$12$kfQHKor0vJMyQSr.oGfhwOustAyXYfzslkgN61qWJmrUu7YX6bFQ2', 'active', NULL, @partner, NULL, NULL, NULL, NULL, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
SET @b_owner = LAST_INSERT_ID();
INSERT INTO `model_has_roles` (`role_id`, `model_type`, `model_id`) SELECT id, 'App\\Models\\User', @b_owner FROM roles WHERE name = 'vip_member' AND guard_name = 'web';

-- The business page
INSERT INTO `vip_microsites` (`user_id`, `city_id`, `vip_plan_id`, `business_name`, `business_category`, `business_sub_category`, `owner_name`, `business_slug`, `description`, `short_description`, `establishment_year`, `gst_no`, `pan_no`, `cin_no`, `logo_path`, `cover_banner_path`, `business_email`, `phone_number`, `alternate_number`, `whatsapp_number`, `website_url`, `address`, `google_map_url`, `business_hours`, `holidays`, `facebook_url`, `instagram_url`, `youtube_url`, `linkedin_url`, `twitter_url`, `telegram_url`, `pinterest_url`, `module_visibility`, `page_layout`, `secure_token`, `status`, `activated_at`, `plan_expires_at`, `created_at`, `updated_at`)
VALUES (@b_owner, @city, @plan_b, 'Rangoli Designer Boutique', 'Fashion & Apparel', 'Women\'s Ethnic Wear Boutique', 'Neha Srivastava', 'rangoli-designer-boutique', 'Rangoli Designer Boutique was started in 2014 by fashion designer Neha Srivastava (NIFT graduate) with two tailors and one sewing machine. Today our team of 14 master tailors and karigars stitches more than 600 outfits every month for brides, working women and families across Bundelkhand.\n\nWe stock handpicked Banarasi, Chanderi and Kanjeevaram sarees, ready-made suits and festive lehengas, and we stitch to your measurements with a free trial fitting. Bridal orders get a dedicated designer from the first sketch to the final fitting.', 'Designer sarees, suits, lehengas and made-to-measure stitching for every occasion — from everyday kurtis to bridal trousseau.', 2014, '09ABKPS4521M1Z8', NULL, NULL, 'uploads/demo/rangoli-boutique/logo.svg', 'uploads/demo/rangoli-boutique/about.jpg', 'hello@rangoliboutique.in', '9876500021', '9876500022', '9876500021', NULL, 'Shop 12, First Floor, Sadar Bazar, near Elite Chauraha, Jhansi, Uttar Pradesh 284001', 'https://maps.google.com/?q=Sadar+Bazar+Jhansi', '{"monday": {"open": "10:30", "close": "21:00", "closed": false}, "tuesday": {"open": "10:30", "close": "21:00", "closed": false}, "wednesday": {"open": "10:30", "close": "21:00", "closed": false}, "thursday": {"open": "10:30", "close": "21:00", "closed": false}, "friday": {"open": "10:30", "close": "21:00", "closed": false}, "saturday": {"open": "10:30", "close": "21:00", "closed": false}, "sunday": {"open": "11:00", "close": "18:00", "closed": false}}', NULL, 'https://facebook.com/', 'https://instagram.com/', NULL, NULL, NULL, NULL, 'https://pinterest.com/', '{"videos": false, "banner": true, "about": true, "stats": true, "shop": true, "services": true, "products": true, "gallery": true, "reviews": true, "contact": true, "faqs": true, "social_media": true, "float_whatsapp": true, "float_call": true, "float_direction": true, "float_email": true}', NULL, 'RNGBTQ7', 'active', '2026-11-01 10:00:00', @expires_b, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
SET @b_ms = LAST_INSERT_ID();

