-- business_faqs (6)
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@b_ms, 'How long does blouse stitching take?', 'Normal stitching takes 5–7 days. Express 48-hour stitching is available for ₹300 extra.', 0, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@b_ms, 'Do you give a trial fitting?', 'Yes. Every stitched outfit gets a free trial fitting, and alterations after the trial are free.', 1, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@b_ms, 'Can I bring my own fabric?', 'Of course. We stitch customer fabric too; charges are the same as listed in our services.', 2, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@b_ms, 'Do you deliver outside Jhansi?', 'Yes, we courier across India within 3–6 days. Bridal outfits are shipped insured.', 3, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@b_ms, 'What is your return policy?', 'Ready-made items can be exchanged within 7 days with tags intact. Stitched and customised orders cannot be returned.', 4, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@b_ms, 'How do I give my measurements from home?', 'Send us a well-fitting blouse or kurta, or book a video call and our designer will guide you.', 5, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');

