INSERT INTO `vip_microsites` (`user_id`, `city_id`, `vip_plan_id`, `business_name`, `business_category`, `business_sub_category`, `owner_name`, `business_slug`, `description`, `short_description`, `establishment_year`, `gst_no`, `pan_no`, `cin_no`, `logo_path`, `cover_banner_path`, `business_email`, `phone_number`, `alternate_number`, `whatsapp_number`, `website_url`, `address`, `google_map_url`, `business_hours`, `holidays`, `facebook_url`, `instagram_url`, `youtube_url`, `linkedin_url`, `twitter_url`, `telegram_url`, `pinterest_url`, `module_visibility`, `page_layout`, `secure_token`, `status`, `activated_at`, `plan_expires_at`, `created_at`, `updated_at`)
VALUES (@g_owner, @city, @plan_g, 'Gitanjali Store', 'Fashion Accessories', 'Ladies Handbags & Purses', 'Gitanjali Agrawal', 'gitanjali-store', 'Gitanjali Store has been Jhansi\'s favourite address for ladies\' bags since 2009. Owner Gitanjali Agrawal personally picks every design from manufacturers in Delhi, Kolkata and Mumbai, so you find the latest styles here first.\n\nFrom everyday totes and office handbags to bridal potlis and party clutches, we stock 1,500+ designs in vegan leather, genuine leather, jute and fabric. Every bag is checked for stitching, zips and lining before it reaches you, and our 6-month warranty covers zip and handle repairs.', 'Ladies handbags, purses, slings, clutches, wallets and travel bags — latest designs at honest prices.', 2009, '09AHFPA7734K1Z2', NULL, NULL, 'uploads/demo/gitanjali-store/logo.svg', 'uploads/demo/gitanjali-store/about.jpg', 'orders@gitanjalistore.in', '9876500031', '9876500032', '9876500031', NULL, '28, Manik Chowk Main Road, opposite Gandhi Udyan, Jhansi, Uttar Pradesh 284002', 'https://maps.google.com/?q=Manik+Chowk+Jhansi', '{"monday": {"open": "10:30", "close": "21:00", "closed": false}, "tuesday": {"open": "10:30", "close": "21:00", "closed": false}, "wednesday": {"open": "10:30", "close": "21:00", "closed": false}, "thursday": {"open": "10:30", "close": "21:00", "closed": false}, "friday": {"open": "10:30", "close": "21:00", "closed": false}, "saturday": {"open": "10:30", "close": "21:00", "closed": false}, "sunday": {"open": "10:30", "close": "21:00", "closed": true}}', NULL, 'https://facebook.com/', 'https://instagram.com/', 'https://youtube.com/', NULL, NULL, NULL, NULL, '{"videos": false, "banner": true, "about": true, "stats": true, "shop": true, "services": true, "products": true, "gallery": true, "reviews": true, "contact": true, "faqs": true, "social_media": true, "float_whatsapp": true, "float_call": true, "float_direction": true, "float_email": true}', NULL, 'GTJSTR9', 'active', '2026-11-01 10:00:00', @expires_g, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
