-- business_faqs (6)
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@g_ms, 'Do you have a warranty on bags?', 'Yes. All bags carry a 6-month warranty on zips and handles; genuine leather bags carry 1 year.', 0, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@g_ms, 'Can I see more colours of a design?', 'Send us the product name on WhatsApp at 98765 00031 and we will share photos of every colour in stock.', 1, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@g_ms, 'Do you deliver?', 'Free delivery in Jhansi on orders above ₹999, usually the same day. We courier across India in 3–5 days.', 2, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@g_ms, 'Can I exchange a bag?', 'Unused bags with tags can be exchanged within 7 days. Sale items and personalised bags cannot be exchanged.', 3, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@g_ms, 'Are your bags genuine leather?', 'Each product says its material. Most designs are vegan (PU) leather; genuine leather items are marked clearly.', 4, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');
INSERT INTO `business_faqs` (`vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`)
VALUES (@g_ms, 'Do you do bulk orders for return gifts?', 'Yes, from 25 pieces with custom packaging. Ask for our Corporate & Bulk Gifting service.', 5, 1, '2026-11-13 10:00:00', '2026-11-13 10:00:00');

